import AxeBuilder from "@axe-core/playwright";
import {
  test,
  expect,
  setThemePlan,
  setThemeQuotaGating,
} from "../helpers/theme-browser";
import { tutorials } from "../../src/components/tutorial-content";

for (const premium of [false, true]) {
  test(`tutorial cards show current ${premium ? "Premium" : "Free"} features`, async ({
    page,
    themeUser,
  }) => {
    test.setTimeout(120000);
    await setThemeQuotaGating(true);
    await setThemePlan(themeUser, premium ? "PAID" : "FREE");
    await page.emulateMedia({ reducedMotion: "reduce" });
    try {
      for (const route of [
        "compose",
        "templates",
        "contacts",
        "usage",
        "history",
        "settings",
      ]) {
        await page.goto(`/${route}`);
        const dialog = page.getByRole("dialog");
        await expect(async () => {
          if (!(await dialog.isVisible()))
            await page
              .getByRole("button", {
                name: `Help with ${route}`,
                exact: true,
              })
              .click();
          await expect(dialog).toBeVisible({ timeout: 1000 });
        }).toPass({ timeout: 10000 });
        const steps = tutorials[`/${route}`];
        for (const [index, step] of steps.entries()) {
          await expect(dialog.locator(".tutorial-title")).toHaveText(
            step.title,
          );
          if (["preview", "resume"].includes(step.hint)) {
            await expect(dialog.locator(".tutorial-text")).toContainText(
              premium ? "Use the color picker" : "Use the crown",
            );
            await expect(dialog.locator(".tutorial-hint")).toContainText(
              premium ? "10 colors" : "crown",
            );
          }
          if (step.hint === "preferences")
            await expect(dialog.locator(".tutorial-hint")).toContainText(
              `1–${premium ? 8 : 2} shortcuts`,
            );
          if (route === "compose" && step.hint === "queue") {
            await expect(dialog.locator(".tutorial-text")).toContainText(
              "individual email",
            );
            await expect(dialog.locator(".tutorial-hint")).toContainText(
              "Selected",
            );
          }
          if (route === "contacts" && step.hint === "import")
            await expect(dialog.locator(".tutorial-hint")).toContainText(
              premium ? "Preview Import" : "Premium required",
            );
          if (route === "history" && step.hint === "statuses") {
            await expect(dialog.locator(".tutorial-text")).toContainText(
              "filter buttons",
            );
            await expect(dialog.locator(".tutorial-hint")).toContainText(
              "Needs review",
            );
          }
          if (step.hint === "subscription") {
            await expect(dialog.locator(".tutorial-hint")).toContainText(
              premium
                ? "Chalk and Obsidian included"
                : "Premium unlocks two more",
            );
            await expect(dialog.locator(".tutorial-hint")).toContainText(
              premium ? "Prioritized email support" : "Ordinary support",
            );
          }
          {
            const bounds = (await dialog
              .locator(".tutorial-card")
              .boundingBox())!;
            expect(bounds.x).toBeGreaterThanOrEqual(0);
            expect(bounds.y).toBeGreaterThanOrEqual(0);
            expect(bounds.x + bounds.width).toBeLessThanOrEqual(
              page.viewportSize()!.width,
            );
            const modal = (await dialog.boundingBox())!;
            expect(modal.y + modal.height).toBeLessThanOrEqual(
              page.viewportSize()!.height,
            );
            await dialog
              .getByRole("button", { name: "Close tutorial" })
              .scrollIntoViewIfNeeded();
            await expect(
              dialog.getByRole("button", { name: "Close tutorial" }),
            ).toBeVisible();
            expect(
              (
                await new AxeBuilder({ page })
                  .include('[role="dialog"]')
                  .analyze()
              ).violations,
            ).toEqual([]);
          }
          if (index < steps.length - 1)
            await dialog
              .getByRole("button", { name: "Next", exact: true })
              .click();
        }
        await dialog.getByRole("button", { name: "Close tutorial" }).click();
      }
    } finally {
      await setThemeQuotaGating(false);
    }
  });
}
